// Join src/*.js and apps-script/Code.gs into one file, dist/Code.gs, to paste
// into the Apps Script editor (Extensions > Apps Script).
//   npm run bundle
// Same file order as tests/load.js, so the tested code is the shipped code.
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { ROOT, SRC_DIR, srcFiles } from "../tests/load.js";

export const DIST_FILE = path.join(ROOT, "dist", "Code.gs");

export function bundle() {
  const read = (file) => fs.readFileSync(file, "utf-8").replace(/\r\n/g, "\n").trimEnd() + "\n";
  const parts = [
    "// Puentara support tracker for Google Sheets (Puentara is a fictional demo company).\n" +
    "// GENERATED by scripts/bundle.js from src/*.js and apps-script/Code.gs.\n" +
    "// Do not edit this file: edit those files, then run `npm run bundle`.\n",
  ];
  for (const file of srcFiles()) {
    parts.push(`// ===== src/${file} =====\n` + read(path.join(SRC_DIR, file)));
  }
  parts.push("// ===== apps-script/Code.gs =====\n" + read(path.join(ROOT, "apps-script", "Code.gs")));
  return parts.join("\n");
}

function main() {
  fs.mkdirSync(path.dirname(DIST_FILE), { recursive: true });
  fs.writeFileSync(DIST_FILE, bundle(), "utf-8");
  const lines = bundle().split("\n").length - 1;
  console.log(`Wrote dist/Code.gs (${lines} lines). Paste it into Extensions > Apps Script, then run setupTracker.`);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) main();
